solution:
#include <stdio.h>
int cong(int a, int b) { return a + b; }
int tru(int a, int b) { return a - b; }
int apply(int (*op)(int, int), int a, int b) { return op(a, b); }
int main(void) {
    int a, b;
    if (scanf("%d %d", &a, &b) != 2) return 1;
    printf("%d\n", apply(cong, a, b));
    printf("%d\n", apply(tru, a, b));
    return 0;
}
